                                controller: scannerController,
                                fit: BoxFit.cover,
                                onDetect: (capture) {
                                  Vibration.vibrate(duration: 15);
                                  final List<Barcode> barcodes =
                                      capture.barcodes;
                                  for (final barcode in barcodes) {
                                    dataQR = "${barcode.rawValue}";
